/**
 * calendar-wc: Standalone calendar display with rich cell content
 *
 * Display component for showing events, availability, or annotations on
 * dates. NOT a form input — use date-picker for date selection in forms.
 * Supports single and range selection, event dots/labels, size variants,
 * year dropdown, day detail overlay, and keyboard navigation.
 *
 * @attr {string}  data-month           - Initial month (1-12). Defaults to current.
 * @attr {string}  data-year            - Initial year. Defaults to current.
 * @attr {string}  data-events          - JSON: events keyed by start ISO date. Values can be:
 *   - string: "Team meeting"
 *   - object: { "label": "...", "color": "...", "icon": "...", "time": "09:00" }
 *   - array:  [{ "label": "...", "time": "..." }, ...]
 *   Add optional `end` (ISO date, inclusive) or `days` (count ≥ 1) to a
 *   value to make it span multiple days; spans render as continuous
 *   bars in data-size="large" and as event dots on every day they cover
 *   in compact/default views.
 * @attr {string}  data-selection       - Selection mode: "none" (default), "single", "range", "multi"
 * @attr {string}  data-size            - Size: "compact", "default", "large"
 * @attr {string}  data-min-date        - Earliest selectable/navigable date (ISO string)
 * @attr {string}  data-max-date        - Latest selectable/navigable date (ISO string)
 * @attr {string}  data-disabled-dates  - Comma-separated ISO dates to disable
 * @attr {string}  data-highlight-dates - Comma-separated ISO dates to highlight (optionally with :category)
 * @attr {string}  data-months          - Number of adjacent months to show (1-12). Defaults to 1.
 * @attr {string}  data-year-range      - Years listed either side of the current year in the year select (default 10, max 200). data-min-date / data-max-date bound a side instead; the displayed year is always listed.
 * @attr {string}  data-heading-level   - Multi-month titles render as <h1>-<h6> at this level. Default: plain text (no heading).
 * @attr {string}  data-label-prev      - Accessible name for the previous-month button (default "Previous month")
 * @attr {string}  data-label-next      - Accessible name for the next-month button (default "Next month")
 * @attr {string}  data-label-year      - Accessible name for the year select (default "Year")
 * @attr {string}  data-label-close     - Accessible name for the day-detail close button (default "Close")
 * @attr {string}  data-label-more      - Large-view overflow text; {n} is replaced by the count (default "+{n} more")
 * @attr {string}  name                - Form participation name (enables ElementInternals form value)
 *
 * data-month, data-year and data-events are observed: changing them re-renders.
 * The other attributes are read on connect (and again on reconnect).
 *
 * @example
 * <calendar-wc data-size="large"
 *   data-events='{"2026-04-10":[{"label":"Standup","time":"09:00","icon":"users"},{"label":"Review","time":"14:00"}]}'>
 * </calendar-wc>
 */

import { registerComponent } from '../../lib/bundle-registry.js';
import { VBElement } from '../../lib/vb-element.js';

// ── Date utilities ──────────────────────────────────────────────────

function toISO(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function fromISO(str) {
  if (!str) return null;
  const [y, m, d] = str.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function daysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

function sameDay(a, b) {
  return a && b &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();
}

function addDays(date, n) {
  const d = new Date(date);
  d.setDate(d.getDate() + n);
  return d;
}

/**
 * Resolve an event's date range. Accepts optional `end` (ISO date) or
 * `days` (count, days ≥ 1). `end` wins if both are present. Returns the
 * key-ISO as both start and end for single-day events; null for invalid.
 */
function resolveRange(evt, keyISO) {
  if (!keyISO) return null;
  const start = fromISO(keyISO);
  if (!start) return null;
  let end = start;
  if (typeof evt === 'object' && evt) {
    if (typeof evt.end === 'string') {
      const e = fromISO(evt.end);
      if (e && e >= start) end = e;
    } else if (typeof evt.days === 'number' && Number.isFinite(evt.days) && evt.days >= 1) {
      end = addDays(start, Math.floor(evt.days) - 1);
    }
  }
  return { start, end, startISO: keyISO, endISO: toISO(end), days: Math.round((end.getTime() - start.getTime()) / 86400000) + 1 };
}

/**
 * First day of the week (0 = Sunday) for a BCP 47 locale. Uses
 * Intl.Locale#getWeekInfo() where shipped, falling back to the older
 * `weekInfo` accessor.
 * @param {string} localeTag
 */
function getFirstDayOfWeek(localeTag) {
  try {
    const locale = /** @type {Intl.Locale & { getWeekInfo?: () => { firstDay: number }, weekInfo?: { firstDay: number } }} */ (new Intl.Locale(localeTag));
    const info = locale.getWeekInfo?.() ?? locale.weekInfo;
    if (info) return info.firstDay % 7;
  } catch { /* fallback */ }
  return 0;
}

let detailIdCounter = 0;

/** Normalize event data to always be an array of event objects */
function normalizeEvents(data) {
  if (!data) return [];
  if (typeof data === 'string') return [{ label: data }];
  if (Array.isArray(data)) return data;
  if (typeof data === 'object') return [data];
  return [];
}

// ── Locale-aware label helpers ──────────────────────────────────────

const _dayCache = new Map();
const _hourCache = new Map();

/**
 * Return an array of 7 weekday names (index 0 = Sunday) for the given locale.
 * @param {string} locale  BCP 47 locale string
 * @param {'short'|'narrow'|'long'} style  Intl weekday format
 */
function getLocalizedDays(locale, style = 'short') {
  const key = `${locale}:${style}`;
  if (_dayCache.has(key)) return _dayCache.get(key);
  const fmt = new Intl.DateTimeFormat(locale, { weekday: style });
  // Jan 4 2026 is a Sunday — iterate 7 consecutive days
  const days = Array.from({ length: 7 }, (_, i) =>
    fmt.format(new Date(2026, 0, 4 + i))
  );
  _dayCache.set(key, days);
  return days;
}

/**
 * Return an array of 24 hour labels for the given locale.
 * @param {string} locale  BCP 47 locale string
 */
function getLocalizedHours(locale) {
  if (_hourCache.has(locale)) return _hourCache.get(locale);
  const fmt = new Intl.DateTimeFormat(locale, { hour: 'numeric' });
  const hours = Array.from({ length: 24 }, (_, i) =>
    fmt.format(new Date(2026, 0, 4, i))
  );
  _hourCache.set(locale, hours);
  return hours;
}

// ── Component ───────────────────────────────────────────────────────

class CalendarWc extends VBElement {
  static formAssociated = true;

  /** @type {ElementInternals} */
  #internals;
  /** @type {string} */
  #locale = 'en-US';
  /** @type {number} */
  #viewMonth = new Date().getMonth();
  /** @type {number} */
  #viewYear = new Date().getFullYear();
  /** @type {number} */
  #firstDayOfWeek = 0;
  /** @type {Record<string, any[]>} */
  #events = {};
  /** @type {Date | null} */
  #minDate = null;
  /** @type {Date | null} */
  #maxDate = null;
  /** @type {Set<string>} */
  #disabledDates = new Set();
  /** @type {Map<string, string>} */
  #highlightDates = new Map();
  /** @type {Date | null} */
  #selectedDate = null;
  /** @type {Set<string>} */
  #selectedDates = new Set();
  /** @type {Date | null} */
  #rangeStart = null;
  /** @type {Date | null} */
  #rangeEnd = null;
  /** @type {Date | null} */
  #hoverDate = null;
  #selectionMode = 'none';
  #size = 'default';
  #monthCount = 1;
  /** ISO date that owns the roving tabindex="0" across all visible months. */
  /** @type {string | null} */
  #focusISO = null;
  /** True once .events was assigned, so a reconnect does not re-read data-events over it. */
  #eventsFromProperty = false;
  /** Set while #renderMonth reflects data-month/data-year, to ignore our own writes. */
  #reflecting = false;

  static get observedAttributes() { return ['data-month', 'data-year', 'data-events']; }

  attributeChangedCallback(name, oldValue, newValue) {
    if (!this.#built || this.#reflecting || oldValue === newValue) return;
    if (name === 'data-events') {
      /** @type {Record<string, any[]>} */
      let next = {};
      if (newValue) {
        try { next = JSON.parse(newValue); } catch { return; }
      }
      this.#eventsFromProperty = false;
      this.#events = next;
      this.#renderMonth();
      this.dispatchEvent(new CustomEvent('calendar-wc:events-changed', {
        detail: { events: next, source: 'attribute' },
        bubbles: true,
      }));
      return;
    }
    const month = parseInt(this.getAttribute('data-month') ?? '', 10) - 1;
    const year = parseInt(this.getAttribute('data-year') ?? '', 10);
    const nextMonth = month >= 0 && month <= 11 ? month : this.#viewMonth;
    const nextYear = Number.isFinite(year) ? year : this.#viewYear;
    if (nextMonth === this.#viewMonth && nextYear === this.#viewYear) return;
    this.#viewMonth = nextMonth;
    this.#viewYear = nextYear;
    this.#renderMonth();
  }

  /** JS-only callback: (date: Date) => boolean. If it returns true, the date is disabled. */
  /** @type {((date: Date) => boolean) | null} */
  #isDateDisallowedFn = null;
  get isDateDisallowed() { return this.#isDateDisallowedFn; }
  set isDateDisallowed(fn) { this.#isDateDisallowedFn = fn; if (this.#built) this.#renderMonth(); }

  /** JS-only callback: (date: Date) => string | string[] | null. Return value set as data-day-part on the cell. */
  /** @type {((date: Date) => string | string[] | null) | null} */
  #getDayPartsFn = null;
  get getDayParts() { return this.#getDayPartsFn; }
  set getDayParts(fn) { this.#getDayPartsFn = fn; if (this.#built) this.#renderMonth(); }

  /**
   * Events as a date-keyed object, the canonical internal shape.
   * Setting accepts EITHER:
   *   - The same object shape: `{ "2026-04-10": [{ label, time, ... }] }`
   *   - A flat array of events: `[{ id, date: "2026-04-10", label, ... }]`
   *     Flat arrays are grouped by `date` automatically.
   * Reading always returns the date-keyed object.
   *
   * @returns {object} Date-keyed events map (`{ [isoDate]: event[] }`).
   */
  get events() { return this.#events; }
  set events(value) {
    const next = this._normalizeEventsInput(value);
    // Identity short-circuit on object reference
    if (this.#events === next) return;
    this.#events = next;
    this.#eventsFromProperty = true;
    if (this.#built) this.#renderMonth();
    this.dispatchEvent(new CustomEvent('calendar-wc:events-changed', {
      detail: { events: next, source: 'property' },
      bubbles: true,
    }));
  }

  /**
   * Normalize either a date-keyed object or a flat event array into
   * the internal date-keyed shape. Flat arrays group entries by `date`,
   * preserving array order within a date.
   *
   * @param {*} value - Date-keyed object, flat event array, or anything else (treated as empty).
   * @returns {object} Date-keyed events map (`{ [isoDate]: event[] }`).
   */
  _normalizeEventsInput(value) {
    if (!value) return {};
    if (Array.isArray(value)) {
      const grouped = {};
      for (const evt of value) {
        const date = evt?.date;
        if (!date) continue;
        if (!grouped[date]) grouped[date] = [];
        grouped[date].push(evt);
      }
      return grouped;
    }
    if (typeof value === 'object') return value;
    return {};
  }

  #built = false;

  // DOM refs
  #header;
  #titleContainer;
  #monthLabel;
  #yearSelect;
  #yearWrap;
  #grid;
  #monthsWrap;
  #prevBtn;
  #nextBtn;
  /** @type {HTMLElement | null} */
  #banner = null;
  /** Element to return focus to when the day detail closes. */
  /** @type {HTMLElement | null} */
  #detailReturnFocus = null;
  /** @type {HTMLDivElement | null} */
  #detailOverlay = null;
  /** @type {(() => void) | null} */
  _detailCleanup = null;
  /** @type {{dayToEvents: Map<string, any[]>, spans: any[]}} */
  #renderData = { dayToEvents: new Map(), spans: [] };

  constructor() {
    super();
    if (typeof this.attachInternals === 'function') {
      this.#internals = this.attachInternals();
      this._adoptInternals(this.#internals);
    }
  }

  setup() {
    this.#locale = /** @type {HTMLElement | null} */ (this.closest('[lang]'))?.lang || navigator.language;
    const today = new Date();
    this.#viewMonth = parseInt(this.getAttribute('data-month') ?? '', 10) - 1;
    if (isNaN(this.#viewMonth)) this.#viewMonth = today.getMonth();
    this.#viewYear = parseInt(this.getAttribute('data-year') ?? '', 10);
    if (isNaN(this.#viewYear)) this.#viewYear = today.getFullYear();
    this.#firstDayOfWeek = getFirstDayOfWeek(this.#locale);
    this.#selectionMode = this.getAttribute('data-selection') || 'none';
    this.#size = this.getAttribute('data-size') || 'default';
    this.#monthCount = Math.max(1, Math.min(12, parseInt(this.dataset.months ?? '', 10) || 1));

    // Parse events (unless the .events property already owns them)
    const eventsAttr = this.getAttribute('data-events');
    if (eventsAttr && !this.#eventsFromProperty) {
      try { this.#events = JSON.parse(eventsAttr); } catch { /* ignore */ }
    }

    // Parse min/max date constraints
    this.#minDate = fromISO(this.dataset.minDate);
    this.#maxDate = fromISO(this.dataset.maxDate);

    // Parse disabled dates
    this.#disabledDates.clear();
    this.#highlightDates.clear();
    const disabled = this.getAttribute('data-disabled-dates');
    if (disabled) {
      disabled.split(',').forEach(d => this.#disabledDates.add(d.trim()));
    }

    // Parse highlighted dates
    const highlights = this.getAttribute('data-highlight-dates');
    if (highlights) {
      highlights.split(',').forEach(entry => {
        const [date, category] = entry.trim().split(':');
        this.#highlightDates.set(date, category || '');
      });
    }

    this.#build();
    this.#renderMonth();
    this.#built = true;
  }

  /** Force a re-render of the current view. Useful after setting JS-only properties. */
  refresh() { if (this.#built) this.#renderMonth(); }

  /**
   * Author-overridable UI string from a data-label-* attribute.
   * @param {string} key  dataset key suffix, e.g. 'Prev' for data-label-prev
   * @param {string} fallback
   */
  #label(key, fallback) {
    return this.dataset[`label${key}`] || fallback;
  }

  #build() {
    // Header
    this.#header = document.createElement('header');

    this.#prevBtn = document.createElement('button');
    this.#prevBtn.type = 'button';
    this.#prevBtn.setAttribute('aria-label', this.#label('Prev', 'Previous month'));
    this.#prevBtn.textContent = '\u2039';
    this.listen(this.#prevBtn, 'click', () => this.#navigate(-1));

    // Title area: month label + year dropdown
    this.#titleContainer = document.createElement('span');
    this.#titleContainer.className = 'calendar-title';
    this.#titleContainer.setAttribute('aria-live', 'polite');

    this.#monthLabel = document.createElement('span');
    this.#monthLabel.className = 'calendar-month';

    this.#yearSelect = document.createElement('select');
    this.#yearSelect.className = 'calendar-year';
    this.#yearSelect.setAttribute('aria-label', this.#label('Year', 'Year'));
    this.listen(this.#yearSelect, 'change', () => {
      this.#viewYear = parseInt(this.#yearSelect.value, 10);
      this.#renderMonth();
      this.dispatchEvent(new CustomEvent('calendar:navigate', {
        bubbles: true, detail: { year: this.#viewYear, month: this.#viewMonth + 1 }
      }));
    });

    this.#yearWrap = document.createElement('span');
    this.#yearWrap.className = 'calendar-year-wrap';
    this.#yearWrap.appendChild(this.#yearSelect);
    this.#titleContainer.append(this.#monthLabel, ' ', this.#yearWrap);

    this.#nextBtn = document.createElement('button');
    this.#nextBtn.type = 'button';
    this.#nextBtn.setAttribute('aria-label', this.#label('Next', 'Next month'));
    this.#nextBtn.textContent = '\u203A';
    this.listen(this.#nextBtn, 'click', () => this.#navigate(1));

    this.#header.append(this.#prevBtn, this.#titleContainer, this.#nextBtn);
    this.appendChild(this.#header);

    // Banner — purely decorative surface for theme imagery
    const banner = document.createElement('div');
    banner.className = 'calendar-banner';
    banner.setAttribute('aria-hidden', 'true');
    this.appendChild(banner);
    this.#banner = banner;

    // Months wrapper — holds 1..N month grids side by side
    this.#monthsWrap = document.createElement('div');
    this.#monthsWrap.className = 'cal-months';
    this.appendChild(this.#monthsWrap);

    // Click delegation — select or open day detail (not both)
    this.listen(this.#monthsWrap, 'click', (e) => {
      const target = /** @type {Element | null} */ (e.target);
      const btn = /** @type {HTMLButtonElement | null} */ (target?.closest('button[data-date]'));
      if (!btn || btn.disabled) return;
      const iso = btn.getAttribute('data-date');
      if (!iso) return;

      if (this.#selectionMode !== 'none') {
        this.#handleSelect(iso);
      } else {
        // Display-only mode: open day detail if any events (including
        // multi-day spans) cover this day.
        const entries = this.#renderData.dayToEvents.get(iso) || [];
        if (entries.length) this.#openDayDetail(iso, entries.map(e => e.evt));
      }
    });

    // Keyboard navigation — delegated on the wrapper. Enter/Space are left
    // to the native <button>, whose activation fires the click handler
    // above: the same select / open-day-detail path as a pointer click.
    this.listen(this.#monthsWrap, 'keydown', (e) => this.#handleKey(/** @type {KeyboardEvent} */ (e)));

    // Roving tabindex follows focus (keyboard or pointer).
    this.listen(this.#monthsWrap, 'focusin', (e) => {
      const target = /** @type {Element | null} */ (e.target);
      const btn = /** @type {HTMLButtonElement | null} */ (target?.closest?.('button[data-date]'));
      if (!btn) return;
      this.#focusISO = btn.getAttribute('data-date');
      this.#applyRovingTabindex();
    });

    // Escape closes the day detail — scoped to this calendar, not the document.
    this.listen(this, 'keydown', (e) => {
      if (/** @type {KeyboardEvent} */ (e).key === 'Escape' && this.#detailOverlay) {
        e.stopPropagation();
        this.#closeDayDetail(true);
      }
    });

    // Hover for range preview — in-place attribute update, no re-render
    if (this.#selectionMode === 'range') {
      this.listen(this.#monthsWrap, 'mouseover', (e) => {
        const target = /** @type {Element | null} */ (e.target);
        const btn = target?.closest('button[data-date]');
        if (btn && this.#rangeStart && !this.#rangeEnd) {
          this.#hoverDate = fromISO(btn.getAttribute('data-date'));
          this.#updateSelectionUI();
        }
      });
    }
  }

  /** Years listed either side of the current year when no min/max date bounds that side (data-year-range, default 10). */
  #yearRange() {
    const n = parseInt(this.getAttribute('data-year-range') ?? '', 10);
    return Number.isFinite(n) && n >= 0 ? Math.min(n, 200) : 10;
  }

  #buildYearOptions() {
    this.#yearSelect.innerHTML = '';
    const currentYear = new Date().getFullYear();
    const span = this.#yearRange();
    // Always include the displayed year, even when it is far from today.
    const minYear = Math.min(this.#viewYear, this.#minDate ? this.#minDate.getFullYear() : currentYear - span);
    const maxYear = Math.max(this.#viewYear, this.#maxDate ? this.#maxDate.getFullYear() : currentYear + span);
    for (let y = minYear; y <= maxYear; y++) {
      const opt = document.createElement('option');
      opt.value = String(y);
      opt.textContent = String(y);
      if (y === this.#viewYear) opt.selected = true;
      this.#yearSelect.appendChild(opt);
    }
  }

  #navigate(direction) {
    this.#viewMonth += direction;
    if (this.#viewMonth < 0) { this.#viewMonth = 11; this.#viewYear--; }
    if (this.#viewMonth > 11) { this.#viewMonth = 0; this.#viewYear++; }
    this.#renderMonth();
    this.dispatchEvent(new CustomEvent('calendar:navigate', {
      bubbles: true,
      detail: { year: this.#viewYear, month: this.#viewMonth + 1 }
    }));
  }

  #handleSelect(iso) {
    if (this.#selectionMode === 'none') return;
    const date = fromISO(iso);
    if (!date) return;

    if (this.#selectionMode === 'single') {
      this.#selectedDate = date;
      this.#updateSelectionUI();
      this.#syncFormValue();
      this.dispatchEvent(new CustomEvent('calendar:select', {
        bubbles: true, detail: { value: iso, date }
      }));
    } else if (this.#selectionMode === 'range') {
      if (!this.#rangeStart || this.#rangeEnd) {
        this.#rangeStart = date;
        this.#rangeEnd = null;
        this.#hoverDate = null;
        this.setAttribute('data-tentative', toISO(this.#rangeStart));
      } else {
        this.#rangeEnd = date;
        if (this.#rangeStart && this.#rangeStart > this.#rangeEnd) {
          [this.#rangeStart, this.#rangeEnd] = [this.#rangeEnd, this.#rangeStart];
        }
        this.#hoverDate = null;
        this.removeAttribute('data-tentative');
        const startISO = toISO(this.#rangeStart);
        const endISO = toISO(this.#rangeEnd);
        this.dispatchEvent(new CustomEvent('calendar:select', {
          bubbles: true,
          detail: {
            value: `${startISO}/${endISO}`,
            start: startISO, end: endISO,
            startDate: this.#rangeStart, endDate: this.#rangeEnd,
          }
        }));
      }
      this.#updateSelectionUI();
      this.#syncFormValue();
    } else if (this.#selectionMode === 'multi') {
      if (this.#selectedDates.has(iso)) {
        this.#selectedDates.delete(iso);
      } else {
        this.#selectedDates.add(iso);
      }
      this.#updateSelectionUI();
      this.#syncFormValue();
      const sorted = [...this.#selectedDates].sort();
      this.dispatchEvent(new CustomEvent('calendar:select', {
        bubbles: true,
        detail: { values: sorted, dates: sorted.map(fromISO) }
      }));
    }
  }

  /** Sync form value via ElementInternals when participating in a form */
  #syncFormValue() {
    if (this.#internals && this.getAttribute('name')) {
      this.#internals.setFormValue(this.value);
    }
  }

  /**
   * Return the current selection as a serializable value
   *
   * @returns {string|null} ISO date, `start/end` range, space-separated dates, or null.
   */
  get value() {
    switch (this.#selectionMode) {
      case 'single':
        return this.#selectedDate ? toISO(this.#selectedDate) : null;
      case 'range':
        if (this.#rangeStart && this.#rangeEnd) {
          return `${toISO(this.#rangeStart)}/${toISO(this.#rangeEnd)}`;
        }
        return this.#rangeStart ? toISO(this.#rangeStart) : null;
      case 'multi':
        return this.#selectedDates.size
          ? [...this.#selectedDates].sort().join(' ')
          : null;
      default:
        return null;
    }
  }

  /** Update selection/range attributes in-place without rebuilding DOM */
  #updateSelectionUI() {
    if (!this.#monthsWrap) return;

    const rangeA = this.#rangeStart;
    const rangeB = this.#rangeEnd || this.#hoverDate;

    for (const td of this.#monthsWrap.querySelectorAll('td')) {
      const btn = td.querySelector('button[data-date]');
      if (!btn) continue;

      const iso = btn.getAttribute('data-date');
      const cellDate = fromISO(iso);
      if (!cellDate || !iso) continue;

      // Clear old selection attributes
      td.removeAttribute('data-selected');
      td.removeAttribute('data-range-start');
      td.removeAttribute('data-range-end');
      td.removeAttribute('data-in-range');

      // Single selection
      if (this.#selectionMode === 'single' && sameDay(cellDate, this.#selectedDate)) {
        td.setAttribute('data-selected', '');
      }

      // Multi selection
      if (this.#selectionMode === 'multi' && this.#selectedDates.has(iso)) {
        td.setAttribute('data-selected', '');
      }

      // Range selection
      if (this.#selectionMode === 'range' && rangeA) {
        if (rangeB) {
          const lo = rangeA < rangeB ? rangeA : rangeB;
          const hi = rangeA < rangeB ? rangeB : rangeA;
          if (sameDay(cellDate, lo)) td.setAttribute('data-range-start', '');
          if (sameDay(cellDate, hi)) td.setAttribute('data-range-end', '');
          if (cellDate >= lo && cellDate <= hi) td.setAttribute('data-in-range', '');
        } else if (sameDay(cellDate, rangeA)) {
          td.setAttribute('data-range-start', '');
        }
      }

      this.#syncAriaSelected(td);
    }
  }

  /**
   * aria-selected lives on the gridcell (<td>), not the <button>: buttons
   * do not support it. Selected = data-selected, or inside a range
   * (start/end/in-range). In a selectable grid every in-month cell gets an
   * explicit true/false; display-only grids carry none.
   * @param {HTMLTableCellElement} td
   */
  #syncAriaSelected(td) {
    if (this.#selectionMode === 'none') { td.removeAttribute('aria-selected'); return; }
    const selected = td.hasAttribute('data-selected') || td.hasAttribute('data-in-range') ||
      td.hasAttribute('data-range-start') || td.hasAttribute('data-range-end');
    td.setAttribute('aria-selected', String(selected));
  }

  /**
   * Exactly one enabled day button across all visible months gets
   * tabindex="0": the last focused day, else the selection, else today,
   * else the first enabled day.
   */
  #applyRovingTabindex() {
    if (!this.#monthsWrap) return;
    const buttons = /** @type {HTMLButtonElement[]} */ ([...this.#monthsWrap.querySelectorAll('button[data-date]')]);
    const enabled = buttons.filter(b => !b.disabled);
    const byISO = (/** @type {string | null} */ iso) => (iso ? enabled.find(b => b.getAttribute('data-date') === iso) : undefined);
    let selectedISO = null;
    if (this.#selectionMode === 'single' && this.#selectedDate) selectedISO = toISO(this.#selectedDate);
    else if (this.#selectionMode === 'range' && this.#rangeStart) selectedISO = toISO(this.#rangeStart);
    else if (this.#selectionMode === 'multi' && this.#selectedDates.size) selectedISO = [...this.#selectedDates].sort()[0];
    const target = byISO(this.#focusISO) || byISO(selectedISO) ||
      enabled.find(b => b.getAttribute('aria-current') === 'date') || enabled[0];
    for (const b of buttons) b.setAttribute('tabindex', b === target ? '0' : '-1');
  }

  /** Compute (year, month) for a given offset from the current view */
  #offsetMonth(offset) {
    const d = new Date(this.#viewYear, this.#viewMonth + offset, 1);
    return { year: d.getFullYear(), month: d.getMonth() };
  }

  /**
   * Resolve all events into an indexed structure used by the renderer:
   *   - dayToEvents : Map<ISO, Array<{evt, range, isSpan, isStart, isEnd}>>
   *   - spans       : list of multi-day events { evt, range }
   * Events may declare `end` (ISO) or `days` (count) for multi-day spans.
   */
  #computeRenderData() {
    const dayToEvents = new Map();
    const spans = [];
    for (const [keyISO, raw] of Object.entries(this.#events || {})) {
      const items = normalizeEvents(raw);
      for (const evt of items) {
        const range = resolveRange(evt, keyISO);
        if (!range) continue;
        const isSpan = range.days > 1;
        if (isSpan) spans.push({ evt, range });
        // Step by calendar day (setDate), not by 24h of milliseconds: a
        // span across a DST change would otherwise duplicate or drop days.
        for (let d = new Date(range.start), guard = 0; guard < range.days; d = addDays(d, 1), guard++) {
          const iso = toISO(d);
          const entry = {
            evt, range, isSpan,
            isStart: iso === range.startISO,
            isEnd: iso === range.endISO,
          };
          if (!dayToEvents.has(iso)) dayToEvents.set(iso, []);
          dayToEvents.get(iso).push(entry);
        }
      }
    }
    return { dayToEvents, spans };
  }

  #renderMonth() {
    const n = this.#monthCount;
    this.#renderData = this.#computeRenderData();
    const fmtMonth = new Intl.DateTimeFormat(this.#locale, { month: 'long' });
    const fmtMonthYear = new Intl.DateTimeFormat(this.#locale, { month: 'long', year: 'numeric' });

    // ── Update shared header title ──
    try {
      const first = new Date(this.#viewYear, this.#viewMonth, 1);
      if (n === 1) {
        this.#monthLabel.textContent = fmtMonth.format(first);
        // Show year dropdown in single-month mode
        if (this.#yearWrap) this.#yearWrap.style.display = '';
      } else {
        // Multi-month: show year(s) in shared header, no dropdown
        const last = this.#offsetMonth(n - 1);
        if (first.getFullYear() === last.year) {
          this.#monthLabel.textContent = String(this.#viewYear);
        } else {
          this.#monthLabel.textContent = `${first.getFullYear()} \u2013 ${last.year}`;
        }
        if (this.#yearWrap) this.#yearWrap.style.display = 'none';
      }
    } catch {
      this.#monthLabel.textContent = String(this.#viewMonth + 1);
    }
    this.#buildYearOptions();

    // ── Constrain prev/next navigation at min/max boundaries ──
    this.#prevBtn.disabled = !!(this.#minDate && (
      this.#viewYear < this.#minDate.getFullYear() ||
      (this.#viewYear === this.#minDate.getFullYear() &&
       this.#viewMonth <= this.#minDate.getMonth())));

    const lastVis = this.#offsetMonth(n - 1);
    this.#nextBtn.disabled = !!(this.#maxDate && (
      lastVis.year > this.#maxDate.getFullYear() ||
      (lastVis.year === this.#maxDate.getFullYear() &&
       lastVis.month >= this.#maxDate.getMonth())));

    // Sync host attributes for theme CSS selectors (ignored by attributeChangedCallback)
    this.#reflecting = true;
    this.setAttribute('data-month', String(this.#viewMonth + 1));
    this.setAttribute('data-year', String(this.#viewYear));
    this.#reflecting = false;

    // ── Build month grids ──
    this.#monthsWrap.innerHTML = '';

    for (let i = 0; i < n; i++) {
      const { year, month } = this.#offsetMonth(i);

      if (n > 1) {
        // Per-month title centered above each grid. The component cannot
        // know the page outline, so it is plain text unless the author sets
        // data-heading-level (1-6). Each table is labelled either way.
        const monthHeader = document.createElement('div');
        monthHeader.className = 'cal-month-column';
        const level = parseInt(this.getAttribute('data-heading-level') ?? '', 10);
        const title = document.createElement(level >= 1 && level <= 6 ? `h${level}` : 'span');
        title.className = 'cal-month-title';
        title.textContent = fmtMonthYear.format(new Date(year, month, 1));
        monthHeader.appendChild(title);
        const table = this.#buildMonthTable(year, month);
        monthHeader.appendChild(table);
        this.#monthsWrap.appendChild(monthHeader);
      } else {
        const table = this.#buildMonthTable(year, month);
        this.#monthsWrap.appendChild(table);
      }
    }

    // Keep #grid pointing at the first table for keyboard nav compatibility
    this.#grid = this.#monthsWrap.querySelector('table');
    this.#applyRovingTabindex();
  }

  /** Build a complete month table (thead + tbody) for the given year/month */
  #buildMonthTable(year, month) {
    const today = new Date();
    const totalDays = daysInMonth(year, month);
    const isLarge = this.#size === 'large';

    const table = document.createElement('table');
    table.setAttribute('role', 'grid');
    if (this.#selectionMode === 'multi' || this.#selectionMode === 'range') {
      table.setAttribute('aria-multiselectable', 'true');
    }
    try {
      const titleDate = new Date(year, month, 1);
      table.setAttribute('aria-label',
        new Intl.DateTimeFormat(this.#locale, { month: 'long', year: 'numeric' }).format(titleDate));
    } catch { /* fallback — no label */ }

    // Weekday headers
    const thead = document.createElement('thead');
    const headerRow = document.createElement('tr');
    const shortDays = getLocalizedDays(this.#locale, 'short');
    const longDays = getLocalizedDays(this.#locale, 'long');
    for (let i = 0; i < 7; i++) {
      const dayIdx = (this.#firstDayOfWeek + i) % 7;
      const th = document.createElement('th');
      th.setAttribute('scope', 'col');
      th.setAttribute('abbr', longDays[dayIdx]);
      th.textContent = shortDays[dayIdx];
      headerRow.appendChild(th);
    }
    thead.appendChild(headerRow);
    table.appendChild(thead);

    // Body
    const tbody = document.createElement('tbody');
    let weekIdx = 1;
    let row = document.createElement('tr');
    row.setAttribute('data-week', String(weekIdx));

    const firstDay = new Date(year, month, 1).getDay();
    const startOffset = (firstDay - this.#firstDayOfWeek + 7) % 7;

    // Leading cells: previous month's trailing days
    const prevMonthDays = daysInMonth(year, month - 1);
    for (let i = 0; i < startOffset; i++) {
      const dayNum = prevMonthDays - startOffset + 1 + i;
      const td = document.createElement('td');
      td.setAttribute('data-outside-month', '');
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.disabled = true;
      btn.setAttribute('tabindex', '-1');
      btn.setAttribute('data-day', String(dayNum));
      const span = document.createElement('span');
      span.className = 'day-number';
      span.textContent = String(dayNum);
      btn.appendChild(span);
      td.appendChild(btn);
      row.appendChild(td);
    }

    const rangeA = this.#rangeStart;
    const rangeB = this.#rangeEnd || this.#hoverDate;

    for (let day = 1; day <= totalDays; day++) {
      const cellDate = new Date(year, month, day);
      const iso = toISO(cellDate);
      const td = document.createElement('td');
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.setAttribute('data-date', iso);

      // Day number
      const dayNum = document.createElement('span');
      dayNum.className = 'day-number';
      dayNum.textContent = String(day);
      btn.appendChild(dayNum);
      btn.setAttribute('data-day', String(day));

      // Today
      if (sameDay(cellDate, today)) {
        btn.setAttribute('aria-current', 'date');
        td.setAttribute('data-today', '');
      }

      // Selected
      if (this.#selectionMode === 'single' && sameDay(cellDate, this.#selectedDate)) {
        td.setAttribute('data-selected', '');
      }

      // Multi selection
      if (this.#selectionMode === 'multi' && this.#selectedDates.has(iso)) {
        td.setAttribute('data-selected', '');
      }

      // Range
      if (this.#selectionMode === 'range' && rangeA && rangeB) {
        const lo = rangeA < rangeB ? rangeA : rangeB;
        const hi = rangeA < rangeB ? rangeB : rangeA;
        if (sameDay(cellDate, lo)) td.setAttribute('data-range-start', '');
        if (sameDay(cellDate, hi)) td.setAttribute('data-range-end', '');
        if (cellDate >= lo && cellDate <= hi) td.setAttribute('data-in-range', '');
      } else if (this.#selectionMode === 'range' && rangeA && sameDay(cellDate, rangeA)) {
        td.setAttribute('data-range-start', '');
      }
      this.#syncAriaSelected(td);

      // Disabled — explicit list, outside min/max range, or isDateDisallowed callback
      const beforeMin = this.#minDate && cellDate < this.#minDate;
      const afterMax = this.#maxDate && cellDate > this.#maxDate;
      const dynamicDisabled = typeof this.isDateDisallowed === 'function' && this.isDateDisallowed(cellDate);
      if (this.#disabledDates.has(iso) || beforeMin || afterMax || dynamicDisabled) {
        btn.setAttribute('aria-disabled', 'true');
        btn.disabled = true;
      }

      // Highlighted
      if (this.#highlightDates.has(iso)) {
        btn.setAttribute('data-highlight', this.#highlightDates.get(iso) || '');
      }

      // Day parts callback
      if (typeof this.getDayParts === 'function') {
        const parts = this.getDayParts(cellDate);
        if (parts != null) {
          td.dataset.dayPart = Array.isArray(parts) ? parts.join(' ') : parts;
        }
      }

      // Events — combines events keyed at this date plus any multi-day
      // span events that cover it.
      const entries = this.#renderData.dayToEvents.get(iso) || [];
      if (entries.length) {
        td.setAttribute('data-events', '');
        td.setAttribute('data-event-count', String(entries.length));

        // Large view: per-cell labels exclude spans (they render as
        // continuous bars instead, injected per row below).
        const cellEntries = isLarge ? entries.filter(e => !e.isSpan) : entries;
        const allEvents = entries.map(e => e.evt);

        if (isLarge) {
          if (cellEntries.length) {
            const eventList = document.createElement('span');
            eventList.className = 'event-list';
            const maxShow = 2;
            cellEntries.slice(0, maxShow).forEach(({ evt }) => {
              const item = document.createElement('span');
              item.className = 'event-item';
              if (evt.color) item.style.setProperty('--event-color', evt.color);
              if (evt.icon) {
                const icon = document.createElement('icon-wc');
                icon.setAttribute('name', evt.icon);
                icon.setAttribute('size', 'xs');
                item.appendChild(icon);
              }
              const text = document.createElement('span');
              text.textContent = evt.time ? `${evt.time} ${evt.label}` : evt.label;
              item.appendChild(text);
              eventList.appendChild(item);
            });
            if (cellEntries.length > maxShow) {
              const more = document.createElement('span');
              more.className = 'event-more';
              more.textContent = this.#label('More', '+{n} more')
                .replace('{n}', String(cellEntries.length - maxShow));
              eventList.appendChild(more);
            }
            btn.appendChild(eventList);
          }
        } else {
          // Default/compact: one dot per event covering this day.
          const dotContainer = document.createElement('span');
          dotContainer.className = 'event-dots';
          dotContainer.setAttribute('aria-hidden', 'true');
          const dotCount = Math.min(entries.length, 3);
          for (let d = 0; d < dotCount; d++) {
            const dot = document.createElement('span');
            dot.setAttribute('data-event-dot', '');
            if (entries[d].evt.color) dot.style.setProperty('--event-color', entries[d].evt.color);
            dotContainer.appendChild(dot);
          }
          td.appendChild(dotContainer);
        }

        // Tooltip with all event labels (includes spans).
        const titles = allEvents.map(e => e.time ? `${e.time} — ${e.label}` : e.label);
        btn.setAttribute('title', titles.join('\n'));
      }

      // Focus management — the single roving tabindex="0" is assigned
      // across all months by #applyRovingTabindex() after rendering.
      btn.setAttribute('tabindex', '-1');

      td.insertBefore(btn, td.firstChild);
      row.appendChild(td);

      if ((startOffset + day) % 7 === 0) {
        tbody.appendChild(row);
        weekIdx++;
        row = document.createElement('tr');
        row.setAttribute('data-week', String(weekIdx));
      }
    }

    // Trailing cells: next month's leading days
    const remaining = (startOffset + totalDays) % 7;
    if (remaining > 0) {
      for (let i = 1; i <= 7 - remaining; i++) {
        const td = document.createElement('td');
        td.setAttribute('data-outside-month', '');
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.disabled = true;
        btn.setAttribute('tabindex', '-1');
        btn.setAttribute('data-day', String(i));
        const span = document.createElement('span');
        span.className = 'day-number';
        span.textContent = String(i);
        btn.appendChild(span);
        td.appendChild(btn);
        row.appendChild(td);
      }
      tbody.appendChild(row);
    }

    table.appendChild(tbody);

    if (isLarge && this.#renderData.spans.length) {
      this.#injectSpanBars(tbody, year, month);
    }

    return table;
  }

  /**
   * Place multi-day event bars across each week row in large view.
   *
   * For every row, find the spans that intersect the row's date range,
   * compute their column extent (1..7) and continuation flags, then
   * greedily pack them into lanes. Each bar lives inside the row's
   * leftmost intersecting cell and uses `inline-size: calc(N * 100%)`
   * to extend across N cells; cells are the positioning context.
   */
  #injectSpanBars(tbody, year, month) {
    const rows = [...tbody.querySelectorAll('tr')];
    const fmtDate = new Intl.DateTimeFormat(this.#locale, { month: 'short', day: 'numeric' });

    for (const row of rows) {
      const cells = [...row.querySelectorAll('td')];
      if (!cells.length) continue;

      // Resolve the date represented by each visible column (handles
      // leading/trailing outside-month cells too).
      const firstInMonthIdx = cells.findIndex(c => c.querySelector('button[data-date]'));
      const colDates = cells.map((td, i) => {
        const btn = td.querySelector('button');
        const iso = btn?.getAttribute('data-date');
        if (iso) return fromISO(iso);
        const day = parseInt(btn?.getAttribute('data-day') || '0', 10);
        const isLeading = firstInMonthIdx >= 0 && i < firstInMonthIdx;
        return isLeading
          ? new Date(year, month - 1, day)
          : new Date(year, month + 1, day);
      });

      const rowStart = colDates[0];
      const rowEnd = colDates[colDates.length - 1];
      if (!rowStart || !rowEnd) continue;

      // Spans that intersect this row, with column extents within it.
      /** @type {Array<{evt: any, range: any, startCol: number, endCol: number, continuesLeft: boolean, continuesRight: boolean, lane?: number}>} */
      const items = [];
      for (const { evt, range } of this.#renderData.spans) {
        if (range.end < rowStart || range.start > rowEnd) continue;
        const lo = range.start < rowStart ? 0 : colDates.findIndex(d => sameDay(d, range.start));
        const hi = range.end > rowEnd ? colDates.length - 1 : colDates.findIndex(d => sameDay(d, range.end));
        if (lo < 0 || hi < 0) continue;
        items.push({
          evt, range,
          startCol: lo, endCol: hi,
          continuesLeft: range.start < rowStart,
          continuesRight: range.end > rowEnd,
        });
      }
      if (!items.length) continue;

      // Greedy lane packing: longer spans first, earlier starts first.
      items.sort((a, b) =>
        (a.startCol - b.startCol) || ((b.endCol - b.startCol) - (a.endCol - a.startCol)));
      /** @type {number[]} */
      const lanes = []; // lanes[laneIdx] = endCol of last placed
      for (const item of items) {
        let lane = 0;
        while (lane < lanes.length && lanes[lane] >= item.startCol) lane++;
        item.lane = lane;
        lanes[lane] = item.endCol;
      }
      const laneCount = lanes.length;
      row.style.setProperty('--cal-row-lanes', String(laneCount));
      row.setAttribute('data-row-lanes', String(laneCount));

      for (const item of items) {
        const host = cells[item.startCol];
        const span = item.endCol - item.startCol + 1;
        const bar = document.createElement('span');
        bar.className = 'event-span';
        bar.style.setProperty('--span-cells', String(span));
        bar.style.setProperty('--span-lane', String(item.lane));
        if (item.evt.color) bar.style.setProperty('--event-color', item.evt.color);
        if (item.continuesLeft) bar.setAttribute('data-continues-start', '');
        if (item.continuesRight) bar.setAttribute('data-continues-end', '');
        bar.textContent = item.evt.label || '';
        bar.setAttribute('title',
          `${item.evt.label} — ${fmtDate.format(item.range.start)} to ${fmtDate.format(item.range.end)}`);
        host.appendChild(bar);
      }
    }
  }

  // ── Day detail overlay ────────────────────────────────────────────

  #openDayDetail(iso, events) {
    this.#closeDayDetail();

    const date = fromISO(iso) ?? new Date();
    // Non-modal dialog: focus moves in on open and returns to the day on
    // close; the page stays operable, so no aria-modal.
    const overlay = document.createElement('div');
    overlay.className = 'day-detail';
    overlay.setAttribute('role', 'dialog');
    const titleId = `calendar-wc-detail-${++detailIdCounter}`;
    overlay.setAttribute('aria-labelledby', titleId);

    // Header
    const header = document.createElement('header');
    const title = document.createElement('h3');
    title.id = titleId;
    try {
      title.textContent = new Intl.DateTimeFormat(this.#locale, {
        weekday: 'long', month: 'long', day: 'numeric', year: 'numeric'
      }).format(date);
    } catch {
      title.textContent = iso;
    }

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.setAttribute('aria-label', this.#label('Close', 'Close'));
    closeBtn.textContent = '\u00D7';
    closeBtn.addEventListener('click', () => this.#closeDayDetail(true));

    header.append(title, closeBtn);
    overlay.appendChild(header);

    // Build day-view with calendar-event children
    const hasTimed = events.some(e => e.time);

    if (hasTimed) {
      const dayView = document.createElement('day-view');
      dayView.dataset.date = iso;
      dayView.dataset.startHour = 'auto';
      dayView.dataset.compact = '';

      const timeFmt = new Intl.DateTimeFormat(this.#locale, {
        hour: 'numeric', minute: '2-digit',
      });

      events.forEach(evt => {
        const ce = document.createElement('calendar-event');
        if (evt.color) ce.style.setProperty('--event-color', evt.color);

        if (evt.icon) {
          const icon = document.createElement('icon-wc');
          icon.setAttribute('name', evt.icon);
          icon.setAttribute('size', 'sm');
          ce.appendChild(icon);
        }

        if (evt.time) {
          const time = document.createElement('time');
          time.setAttribute('datetime', evt.time);
          try {
            const [h, m] = evt.time.split(':');
            const d = new Date(2026, 0, 1, parseInt(h, 10), parseInt(m, 10));
            time.textContent = timeFmt.format(d);
          } catch {
            time.textContent = evt.time;
          }
          ce.appendChild(time);
        }

        ce.append(evt.label || '');
        dayView.appendChild(ce);
      });

      overlay.appendChild(dayView);
    } else {
      // Untimed-only: simple event list
      const list = document.createElement('ul');
      list.className = 'detail-list';
      events.forEach(evt => {
        const li = document.createElement('li');
        if (evt.color) li.style.setProperty('--event-color', evt.color);

        const dot = document.createElement('span');
        dot.className = 'detail-dot';

        const content = document.createElement('span');
        content.className = 'detail-content';

        if (evt.icon) {
          const icon = document.createElement('icon-wc');
          icon.setAttribute('name', evt.icon);
          icon.setAttribute('size', 'sm');
          content.appendChild(icon);
        }

        const label = document.createElement('span');
        label.className = 'detail-label';
        label.textContent = evt.label || '';

        content.append(label);
        li.append(dot, content);
        list.appendChild(li);
      });
      overlay.appendChild(list);
    }

    this.#detailReturnFocus = /** @type {HTMLElement | null} */ (
      this.#monthsWrap.querySelector(`button[data-date="${iso}"]`));
    this.appendChild(overlay);
    this.#detailOverlay = overlay;
    closeBtn.focus();

    // Close on click outside the overlay (Escape is handled on the host,
    // see #build — scoped to this calendar). Outside clicks do not pull
    // focus back: the user is moving elsewhere.
    const onClick = (e) => {
      if (!overlay.contains(e.target)) this.#closeDayDetail(false);
    };
    let raf = 0;
    this._detailCleanup = () => {
      cancelAnimationFrame(raf);
      document.removeEventListener('mousedown', onClick);
    };
    // Use mousedown + rAF to skip the current event that opened the overlay
    raf = requestAnimationFrame(() => {
      document.addEventListener('mousedown', onClick);
    });

    this.dispatchEvent(new CustomEvent('calendar:day-open', {
      bubbles: true, detail: { date: iso, events }
    }));
  }

  /** @param {boolean} [restoreFocus] Return focus to the day that opened the detail. */
  #closeDayDetail(restoreFocus = false) {
    if (this.#detailOverlay) {
      this._detailCleanup?.();
      this._detailCleanup = null;
      this.#detailOverlay.remove();
      this.#detailOverlay = null;
      const back = this.#detailReturnFocus;
      this.#detailReturnFocus = null;
      if (restoreFocus && back?.isConnected) back.focus();
    }
  }

  teardown() {
    this.removeAttribute('data-tentative');
    this.#closeDayDetail();
    // Remove everything #build() appended so a reconnect (setup() runs
    // again) rebuilds once instead of duplicating the header and grid.
    this.#header?.remove();
    this.#banner?.remove();
    this.#monthsWrap?.remove();
    this.#header = this.#banner = this.#monthsWrap = null;
    this.#built = false;
  }

  // ── Keyboard navigation ───────────────────────────────────────────

  /** @param {KeyboardEvent} e */
  #handleKey(e) {
    const steps = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 7, ArrowUp: -7 };
    let step = steps[/** @type {keyof typeof steps} */ (e.key)];
    if (!step) return;

    // Start from the day that has focus, not the first tabindex="0".
    const target = /** @type {Element | null} */ (e.target);
    const focused = /** @type {HTMLButtonElement | null} */ (target?.closest?.('button[data-date]'));
    if (!focused || !this.#monthsWrap.contains(focused)) return;
    const date = fromISO(focused.getAttribute('data-date'));
    if (!date) return;

    e.preventDefault();

    // Columns run right-to-left in RTL: mirror the horizontal arrows.
    if (Math.abs(step) === 1 && getComputedStyle(this).direction === 'rtl') step = -step;

    // Walk in the arrow's direction, skipping disabled days, until an
    // enabled day is found or a min/max bound is hit.
    let newDate = addDays(date, step);
    for (let tries = 0; tries < 366; tries++, newDate = addDays(newDate, step)) {
      if (this.#minDate && newDate < this.#minDate) return;
      if (this.#maxDate && newDate > this.#maxDate) return;

      const newM = newDate.getMonth();
      const newY = newDate.getFullYear();
      const lastVis = this.#offsetMonth(this.#monthCount - 1);
      const inView = (newY > this.#viewYear || (newY === this.#viewYear && newM >= this.#viewMonth)) &&
                     (newY < lastVis.year || (newY === lastVis.year && newM <= lastVis.month));
      const newISO = toISO(newDate);
      if (!inView) {
        // Shift view so the new date is visible
        this.#viewMonth = newM;
        this.#viewYear = newY;
        this.#focusISO = newISO;
        this.#renderMonth();
      }

      const newBtn = /** @type {HTMLButtonElement | null} */ (
        this.#monthsWrap.querySelector(`button[data-date="${newISO}"]`));
      if (newBtn && !newBtn.disabled) {
        this.#focusISO = newISO;
        this.#applyRovingTabindex();
        newBtn.focus();
        return;
      }
    }
  }
}

registerComponent('calendar-wc', CalendarWc);

export { CalendarWc };
